import { Ui } from "foldkit";

export const { Model } = Ui.FileDrop;
export type Model = Ui.FileDrop.Model;

export const {
  DroppedFiles,
  DroppedNonFiles,
  EnteredDragZone,
  LeftDragZone,
  Message,
} = Ui.FileDrop;
export type Message = Ui.FileDrop.Message;

export const { OutMessage, ReceivedFiles, RejectedNonFiles } = Ui.FileDrop;
export type OutMessage = Ui.FileDrop.OutMessage;

export const { init, update, view } = Ui.FileDrop;

export type InitConfig = Ui.FileDrop.InitConfig;
export type ViewInputs = Ui.FileDrop.ViewInputs;
export type FileDropAttributes = Ui.FileDrop.FileDropAttributes;

export {
  dropZoneClasses,
  fileInputClasses,
  fileListClasses,
  fileNameClasses,
  fileRowClasses,
  fileSizeClasses,
  formatFileSize,
  primaryTextClasses,
  secondaryTextClasses,
} from "./view";

import { Match as M, Number } from "effect";

export const dropZoneClasses =
  "flex min-h-44 w-full cursor-pointer select-none flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed border-gray-300 bg-gray-50 px-6 py-8 text-center transition-colors hover:border-accent-400 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50 data-[drag-over]:border-accent-600 data-[drag-over]:bg-accent-50";

export const primaryTextClasses = "text-sm font-semibold text-gray-950";

export const secondaryTextClasses = "text-sm text-gray-600";

export const fileInputClasses = "max-w-full text-sm";

export const fileListClasses = "space-y-2";

export const fileRowClasses =
  "flex items-center justify-between gap-3 rounded-md border border-gray-200 bg-white px-3 py-2";

export const fileNameClasses = "truncate text-sm font-medium text-gray-900";

export const fileSizeClasses = "text-xs text-gray-500";

const BYTES_PER_KB = 1024;
const BYTES_PER_MB = BYTES_PER_KB * BYTES_PER_KB;

export const formatFileSize = (bytes: number): string =>
  M.value(bytes).pipe(
    M.when(Number.isLessThan(BYTES_PER_KB), () => `${bytes} B`),
    M.when(
      Number.isLessThan(BYTES_PER_MB),
      () => `${(bytes / BYTES_PER_KB).toFixed(1)} KB`
    ),
    M.orElse(() => `${(bytes / BYTES_PER_MB).toFixed(1)} MB`)
  );

import { Match as M, Option, Schema as S } from "effect";
import { Command, File, Scene, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";
import { describe, test } from "vitest";

import * as FileDrop from "./index";

const GotFileDropMessage = m("GotFileDropMessage", {
  message: FileDrop.Message,
});

const Model = S.Struct({
  fileDrop: FileDrop.Model,
  files: S.Array(File.File),
  status: S.String,
});

type Model = typeof Model.Type;

const Message = S.Union([GotFileDropMessage]);
type Message = typeof Message.Type;

const initialModel: Model = {
  fileDrop: FileDrop.init({ id: "documents-file-drop" }),
  files: [],
  status: "Waiting for files.",
};

const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotFileDropMessage: ({ message }) => {
        const [fileDrop, commands, maybeOutMessage] = FileDrop.update(
          model.fileDrop,
          message
        );

        const nextModel = Option.match(maybeOutMessage, {
          onNone: () => evo(model, { fileDrop: () => fileDrop }),
          onSome: M.type<FileDrop.OutMessage>().pipe(
            M.tagsExhaustive({
              ReceivedFiles: ({ files }) =>
                evo(model, {
                  fileDrop: () => fileDrop,
                  files: () => [...model.files, ...files],
                  status: () => `Received ${files.length} file(s).`,
                }),
              RejectedNonFiles: () =>
                evo(model, {
                  fileDrop: () => fileDrop,
                  status: () => "Only files can be dropped.",
                }),
            })
          ),
        });

        return [
          nextModel,
          Command.mapMessages(commands, (message) =>
            GotFileDropMessage({ message })
          ),
        ];
      },
    })
  );

const fileDropView = (
  model: Model,
  inputs: Omit<FileDrop.ViewInputs, "toView"> = {}
): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-3")],
    [
      h.submodel({
        slotId: model.fileDrop.id,
        model: model.fileDrop,
        view: FileDrop.view,
        viewInputs: {
          ...inputs,
          toView: (attributes) =>
            h.label(
              [
                ...attributes.root,
                h.Class(FileDrop.dropZoneClasses),
                h.DataAttribute("testid", "file-drop-zone"),
              ],
              [
                h.span(
                  [h.Class(FileDrop.primaryTextClasses)],
                  ["Drop files or click to browse"]
                ),
                h.span(
                  [h.Class(FileDrop.secondaryTextClasses)],
                  ["Documents, images, or other local files."]
                ),
                h.input([
                  ...attributes.input,
                  h.AriaLabel("Upload files"),
                  h.Class(FileDrop.fileInputClasses),
                ]),
              ]
            ),
        },
        toParentMessage: (message) => GotFileDropMessage({ message }),
      }),
      h.p([], [model.status]),
      h.ul(
        [h.Class(FileDrop.fileListClasses)],
        model.files.map((file) =>
          h.li(
            [h.Class(FileDrop.fileRowClasses)],
            [
              h.span([h.Class(FileDrop.fileNameClasses)], [File.name(file)]),
              h.span(
                [h.Class(FileDrop.fileSizeClasses)],
                [FileDrop.formatFileSize(File.size(file))]
              ),
            ]
          )
        )
      ),
    ]
  );
};

const view = Submodel.defineView<Model, Message>(
  (model): Html => fileDropView(model, { multiple: true })
);

const disabledView = Submodel.defineView<Model, Message>(
  (model): Html => fileDropView(model, { isDisabled: true })
);

describe("FileDrop registry view", () => {
  test("receives dropped files and renders file metadata", () => {
    const file = new globalThis.File(["hello"], "report.txt", {
      type: "text/plain",
    });

    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.expect(Scene.text("Waiting for files.")).toExist(),
      Scene.dropFiles(Scene.testId("file-drop-zone"), [file]),
      Scene.expect(Scene.text("Received 1 file(s).")).toExist(),
      Scene.expect(Scene.text("report.txt")).toExist(),
      Scene.expect(Scene.text("5 B")).toExist()
    );
  });

  test("receives input-selected files", () => {
    const file = new globalThis.File(["image"], "photo.png", {
      type: "image/png",
    });

    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.changeFiles(Scene.label("Upload files"), [file]),
      Scene.expect(Scene.text("photo.png")).toExist()
    );
  });

  test("supports disabled state", () => {
    Scene.scene(
      { update, view: disabledView },
      Scene.with(initialModel),
      Scene.expect(Scene.text("Drop files or click to browse")).toExist(),
      Scene.expect(Scene.label("Upload files")).toBeDisabled()
    );
  });
});
